CREATE TABLE public.favourites (user_id uuid NOT NULL, provider_id uuid NOT NULL REFERENCES public.provider_profiles(id) ON DELETE CASCADE, created_at timestamptz NOT NULL DEFAULT now(), PRIMARY KEY(user_id,provider_id));
GRANT SELECT,INSERT,DELETE ON public.favourites TO authenticated; GRANT ALL ON public.favourites TO service_role; ALTER TABLE public.favourites ENABLE ROW LEVEL SECURITY; CREATE POLICY "favourites_own" ON public.favourites FOR ALL TO authenticated USING(user_id=auth.uid()) WITH CHECK(user_id=auth.uid());
CREATE TABLE public.booking_messages (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),booking_id uuid NOT NULL REFERENCES public.bookings(id) ON DELETE CASCADE,sender_id uuid NOT NULL,message text NOT NULL CHECK(length(message) BETWEEN 1 AND 1000),created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT,INSERT ON public.booking_messages TO authenticated; GRANT ALL ON public.booking_messages TO service_role; ALTER TABLE public.booking_messages ENABLE ROW LEVEL SECURITY; CREATE POLICY "messages_participants" ON public.booking_messages FOR SELECT TO authenticated USING(EXISTS(SELECT 1 FROM public.bookings b LEFT JOIN public.provider_profiles p ON p.id=b.provider_id WHERE b.id=booking_id AND (b.customer_id=auth.uid() OR p.user_id=auth.uid() OR public.has_role(auth.uid(),'admin')))); CREATE POLICY "messages_send" ON public.booking_messages FOR INSERT TO authenticated WITH CHECK(sender_id=auth.uid() AND EXISTS(SELECT 1 FROM public.bookings b LEFT JOIN public.provider_profiles p ON p.id=b.provider_id WHERE b.id=booking_id AND (b.customer_id=auth.uid() OR p.user_id=auth.uid())));
CREATE TABLE public.reviews (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),booking_id uuid NOT NULL UNIQUE REFERENCES public.bookings(id),customer_id uuid NOT NULL,provider_id uuid NOT NULL REFERENCES public.provider_profiles(id),rating integer NOT NULL CHECK(rating BETWEEN 1 AND 5),comment text,created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.reviews TO anon,authenticated; GRANT INSERT,UPDATE,DELETE ON public.reviews TO authenticated; GRANT ALL ON public.reviews TO service_role; ALTER TABLE public.reviews ENABLE ROW LEVEL SECURITY; CREATE POLICY "reviews_public" ON public.reviews FOR SELECT TO anon,authenticated USING(true); CREATE POLICY "reviews_customer_create" ON public.reviews FOR INSERT TO authenticated WITH CHECK(customer_id=auth.uid() AND EXISTS(SELECT 1 FROM public.bookings b WHERE b.id=booking_id AND b.customer_id=auth.uid() AND b.provider_id=provider_id AND b.status='completed'));
CREATE TABLE public.payment_methods (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),method text NOT NULL UNIQUE CHECK(method IN('qr','upi','bank','paypal')),label text NOT NULL,is_enabled boolean NOT NULL DEFAULT false,details jsonb NOT NULL DEFAULT '{}',demo_mode boolean NOT NULL DEFAULT false,updated_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.payment_methods TO authenticated; GRANT INSERT,UPDATE,DELETE ON public.payment_methods TO authenticated; GRANT ALL ON public.payment_methods TO service_role; ALTER TABLE public.payment_methods ENABLE ROW LEVEL SECURITY; CREATE POLICY "payment_methods_read" ON public.payment_methods FOR SELECT TO authenticated USING(is_enabled OR public.has_role(auth.uid(),'admin')); CREATE POLICY "payment_methods_admin" ON public.payment_methods FOR ALL TO authenticated USING(public.has_role(auth.uid(),'admin')) WITH CHECK(public.has_role(auth.uid(),'admin'));
ALTER TABLE public.payments ADD COLUMN transaction_reference text, ADD COLUMN expires_at timestamptz, ADD COLUMN verification_note text, ADD COLUMN verified_by uuid, ADD COLUMN verified_at timestamptz;
CREATE TABLE public.wallets (provider_id uuid PRIMARY KEY REFERENCES public.provider_profiles(id) ON DELETE CASCADE,balance numeric(12,2) NOT NULL DEFAULT 0 CHECK(balance>=0),lifetime_earnings numeric(12,2) NOT NULL DEFAULT 0 CHECK(lifetime_earnings>=0),updated_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.wallets TO authenticated; GRANT ALL ON public.wallets TO service_role; ALTER TABLE public.wallets ENABLE ROW LEVEL SECURITY; CREATE POLICY "wallet_owner_admin" ON public.wallets FOR SELECT TO authenticated USING(EXISTS(SELECT 1 FROM public.provider_profiles p WHERE p.id=provider_id AND p.user_id=auth.uid()) OR public.has_role(auth.uid(),'admin'));
CREATE TABLE public.wallet_transactions (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),provider_id uuid NOT NULL REFERENCES public.provider_profiles(id),booking_id uuid REFERENCES public.bookings(id),kind text NOT NULL CHECK(kind IN('earning','commission','withdrawal','refund','adjustment')),amount numeric(12,2) NOT NULL,description text,created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.wallet_transactions TO authenticated; GRANT ALL ON public.wallet_transactions TO service_role; ALTER TABLE public.wallet_transactions ENABLE ROW LEVEL SECURITY; CREATE POLICY "wallet_tx_owner_admin" ON public.wallet_transactions FOR SELECT TO authenticated USING(EXISTS(SELECT 1 FROM public.provider_profiles p WHERE p.id=provider_id AND p.user_id=auth.uid()) OR public.has_role(auth.uid(),'admin'));
CREATE TABLE public.withdrawal_requests (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),provider_id uuid NOT NULL REFERENCES public.provider_profiles(id),amount numeric(12,2) NOT NULL CHECK(amount>0),method text NOT NULL CHECK(method IN('upi','bank')),payout_details jsonb NOT NULL,status text NOT NULL DEFAULT 'pending' CHECK(status IN('pending','approved','paid','rejected')),admin_note text,reviewed_by uuid,reviewed_at timestamptz,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT,INSERT ON public.withdrawal_requests TO authenticated; GRANT UPDATE ON public.withdrawal_requests TO authenticated; GRANT ALL ON public.withdrawal_requests TO service_role; ALTER TABLE public.withdrawal_requests ENABLE ROW LEVEL SECURITY; CREATE POLICY "withdrawals_owner_admin_read" ON public.withdrawal_requests FOR SELECT TO authenticated USING(EXISTS(SELECT 1 FROM public.provider_profiles p WHERE p.id=provider_id AND p.user_id=auth.uid()) OR public.has_role(auth.uid(),'admin')); CREATE POLICY "withdrawals_owner_create" ON public.withdrawal_requests FOR INSERT TO authenticated WITH CHECK(EXISTS(SELECT 1 FROM public.provider_profiles p WHERE p.id=provider_id AND p.user_id=auth.uid())); CREATE POLICY "withdrawals_admin_update" ON public.withdrawal_requests FOR UPDATE TO authenticated USING(public.has_role(auth.uid(),'admin')) WITH CHECK(public.has_role(auth.uid(),'admin'));
CREATE TABLE public.subscription_plans (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),name text NOT NULL UNIQUE,price numeric(10,2) NOT NULL DEFAULT 0,benefits jsonb NOT NULL DEFAULT '[]',is_active boolean NOT NULL DEFAULT true,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.subscription_plans TO anon,authenticated; GRANT INSERT,UPDATE,DELETE ON public.subscription_plans TO authenticated; GRANT ALL ON public.subscription_plans TO service_role; ALTER TABLE public.subscription_plans ENABLE ROW LEVEL SECURITY; CREATE POLICY "plans_public" ON public.subscription_plans FOR SELECT TO anon,authenticated USING(is_active OR public.has_role(auth.uid(),'admin')); CREATE POLICY "plans_admin" ON public.subscription_plans FOR ALL TO authenticated USING(public.has_role(auth.uid(),'admin')) WITH CHECK(public.has_role(auth.uid(),'admin'));
CREATE TABLE public.provider_subscriptions (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),provider_id uuid NOT NULL REFERENCES public.provider_profiles(id),plan_id uuid NOT NULL REFERENCES public.subscription_plans(id),status text NOT NULL DEFAULT 'active' CHECK(status IN('active','expired','cancelled')),starts_at timestamptz NOT NULL DEFAULT now(),expires_at timestamptz,created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT,INSERT ON public.provider_subscriptions TO authenticated; GRANT ALL ON public.provider_subscriptions TO service_role; ALTER TABLE public.provider_subscriptions ENABLE ROW LEVEL SECURITY; CREATE POLICY "subscriptions_owner_admin" ON public.provider_subscriptions FOR SELECT TO authenticated USING(EXISTS(SELECT 1 FROM public.provider_profiles p WHERE p.id=provider_id AND p.user_id=auth.uid()) OR public.has_role(auth.uid(),'admin'));
CREATE TABLE public.coupons (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),code text NOT NULL UNIQUE,discount_type text NOT NULL CHECK(discount_type IN('percent','fixed')),discount_value numeric(10,2) NOT NULL CHECK(discount_value>0),minimum_booking numeric(10,2) NOT NULL DEFAULT 0,expires_at timestamptz NOT NULL,usage_limit integer,used_count integer NOT NULL DEFAULT 0,is_active boolean NOT NULL DEFAULT true,created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.coupons TO authenticated; GRANT INSERT,UPDATE,DELETE ON public.coupons TO authenticated; GRANT ALL ON public.coupons TO service_role; ALTER TABLE public.coupons ENABLE ROW LEVEL SECURITY; CREATE POLICY "coupons_available" ON public.coupons FOR SELECT TO authenticated USING(is_active OR public.has_role(auth.uid(),'admin')); CREATE POLICY "coupons_admin" ON public.coupons FOR ALL TO authenticated USING(public.has_role(auth.uid(),'admin')) WITH CHECK(public.has_role(auth.uid(),'admin'));
CREATE TABLE public.referrals (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),referrer_id uuid NOT NULL,referred_id uuid NOT NULL UNIQUE,reward_amount numeric(10,2) NOT NULL DEFAULT 0,status text NOT NULL DEFAULT 'pending' CHECK(status IN('pending','earned','paid')),created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.referrals TO authenticated; GRANT ALL ON public.referrals TO service_role; ALTER TABLE public.referrals ENABLE ROW LEVEL SECURITY; CREATE POLICY "referrals_participant" ON public.referrals FOR SELECT TO authenticated USING(referrer_id=auth.uid() OR referred_id=auth.uid() OR public.has_role(auth.uid(),'admin'));
CREATE TABLE public.user_reports (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),reporter_id uuid NOT NULL,target_provider_id uuid REFERENCES public.provider_profiles(id),booking_id uuid REFERENCES public.bookings(id),reason text NOT NULL,details text,status text NOT NULL DEFAULT 'open' CHECK(status IN('open','reviewing','resolved','dismissed')),created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT,INSERT,UPDATE ON public.user_reports TO authenticated; GRANT ALL ON public.user_reports TO service_role; ALTER TABLE public.user_reports ENABLE ROW LEVEL SECURITY; CREATE POLICY "reports_owner_admin_read" ON public.user_reports FOR SELECT TO authenticated USING(reporter_id=auth.uid() OR public.has_role(auth.uid(),'admin')); CREATE POLICY "reports_create" ON public.user_reports FOR INSERT TO authenticated WITH CHECK(reporter_id=auth.uid()); CREATE POLICY "reports_admin_update" ON public.user_reports FOR UPDATE TO authenticated USING(public.has_role(auth.uid(),'admin')) WITH CHECK(public.has_role(auth.uid(),'admin'));
CREATE TABLE public.booking_disputes (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),booking_id uuid NOT NULL REFERENCES public.bookings(id),raised_by uuid NOT NULL,reason text NOT NULL,status text NOT NULL DEFAULT 'open' CHECK(status IN('open','reviewing','resolved','rejected')),resolution text,reviewed_by uuid,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT,INSERT,UPDATE ON public.booking_disputes TO authenticated; GRANT ALL ON public.booking_disputes TO service_role; ALTER TABLE public.booking_disputes ENABLE ROW LEVEL SECURITY; CREATE POLICY "disputes_participants" ON public.booking_disputes FOR SELECT TO authenticated USING(raised_by=auth.uid() OR public.has_role(auth.uid(),'admin') OR EXISTS(SELECT 1 FROM public.bookings b JOIN public.provider_profiles p ON p.id=b.provider_id WHERE b.id=booking_id AND p.user_id=auth.uid())); CREATE POLICY "disputes_create" ON public.booking_disputes FOR INSERT TO authenticated WITH CHECK(raised_by=auth.uid()); CREATE POLICY "disputes_admin_update" ON public.booking_disputes FOR UPDATE TO authenticated USING(public.has_role(auth.uid(),'admin')) WITH CHECK(public.has_role(auth.uid(),'admin'));
CREATE TABLE public.notifications (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),user_id uuid NOT NULL,type text NOT NULL,title text NOT NULL,message text NOT NULL,data jsonb NOT NULL DEFAULT '{}',read_at timestamptz,created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT,UPDATE,DELETE ON public.notifications TO authenticated; GRANT ALL ON public.notifications TO service_role; ALTER TABLE public.notifications ENABLE ROW LEVEL SECURITY; CREATE POLICY "notifications_own" ON public.notifications FOR ALL TO authenticated USING(user_id=auth.uid()) WITH CHECK(user_id=auth.uid());
INSERT INTO public.subscription_plans(name,price,benefits) VALUES('Free',0,'["Standard listing"]'),('Basic',299,'["Priority listing","Provider analytics"]'),('Premium',699,'["Featured listing","Priority support","Advanced analytics"]') ON CONFLICT DO NOTHING;
